//! Derivación de la decisión prefijada a partir de recepción y revisión exterior identificadas.
use super::*;
fn valor(contenido:&str,revision:&str,formal:bool)->R<&'static str>{
 need(["0","1","U"].contains(&contenido)&&["0","1","U"].contains(&revision),"Valor ajeno")?;
 Ok(if !formal||contenido=="1"||revision=="1"{"1"}else if contenido=="U"||revision=="U"{"U"}else{"0"})
}
fn html(s:&str)->String{s.replace('&',"&amp;").replace('<',"&lt;").replace('>',"&gt;").replace('"',"&quot;")}
pub fn cerrar(base:&Path,r:&Value)->R<Value>{
 need(r["conforme"]==true&&r["completo"]==true&&r["intentos"]==3&&r["entregas"]==3,"Recepción incompleta o alcance distinto")?;
 let key=read(&base.join("reservado/CLAVE.json"))?;need(sha(&key)=="f3931b329331b79d9bee47296e22fb0da0b5d7ce68388ca2a88217c500dd1de9","Clave distinta")?;
 let rvb=read(&base.join("REVISION-SUSTANTIVA.json"))?;let rv=parse(&rvb)?;let a=rv["etapas"].as_array().ok_or("Revisión ausente")?;need(a.len()==3&&rv["caso"]=="MD01"&&rv["version"]=="1.1.0-md01-diagnostica","Revisión ajena")?;
 let mut resultados=vec![];let mut respuestas=String::new();let mut filas=String::new();
 for (i,x) in r["casos"].as_array().ok_or("Casos ausentes")?.iter().enumerate(){
  let v=&a[i];need(v["etapa"]==i&&x["etapa"]==i&&x["caso"]=="MD01"&&x["completa"]==true,"Orden o caso distintos")?;
  let text=x["respuesta"].as_str().ok_or("Respuesta ausente")?;need(v["final_sha256"]==sha(text.as_bytes())&&v["final_sha256"]==x["final_sha256"],"Revisión de otro original")?;
  need(v["fundamento"].as_str().is_some_and(|s|!s.trim().is_empty()),"Revisión sin fundamento")?;
  let final_v=parse(text.as_bytes())?;if i>0 {need(final_v["revision"].as_str().ok_or("Revisión")?.contains(v["cotejo_historia"].as_str().ok_or("Cotejo")?),"Cita histórica discordante")?;}
  let code=valor(v["contenido"].as_str().ok_or("Contenido")?,v["revision"].as_str().ok_or("Revisión")?,x["formal_conforme"]==true)?;
  need(code!="0"||final_v["estado_documental"]=="respuesta_fundada","U no admite conformidad sin revisión")?;
  let out=json!({"caso":"MD01","etapa":i,"valor":code,"critica":true,"contenido":v["contenido"],"estructura_conforme":x["formal_conforme"],"revision":v["revision"],"fundamento":v["fundamento"],"advertencia_documental":rv["advertencia_documental"],"original_sha256":x["final_sha256"],"revision_sustantiva_sha256":sha(&rvb),"autoria_licencia":PIE});
  save(&base.join(format!("hitos/INTENTO-{:03}/ADJUDICACION.json",i+1)),&out)?;resultados.push(out);
  filas+=&format!("<tr><th>R{i}</th><td>{code}</td><td>{}</td></tr>",html(v["fundamento"].as_str().unwrap()));
  respuestas+=&format!("<details><summary>Respuesta original R{i} y huella</summary><p><code>{}</code></p><pre>{}</pre></details>",html(x["final_sha256"].as_str().unwrap()),html(text));
 }
 let apto=resultados.iter().all(|v|v["valor"]=="0");let verdict=if apto{"Conforme para la réplica diagnóstica MD01"}else{"No conforme para la réplica diagnóstica MD01"};
 let out=json!({"caso":"MD01","version":"1.1.0-md01-diagnostica","dictamen":verdict,"conforme":apto,"critica":true,"etapas":resultados,"recepcion_sha256":sha(&read(&base.join("RECEPCION-RUST.json"))?),"revision_sustantiva_sha256":sha(&rvb),"clave_prefijada_sha256":sha(&key),"limites":rv["limites"],"revision_exterior":rv["naturaleza"],"adjudicacion_automatica_semantica":false,"vector_original_modificado":false,"nuevas_inferencias_durante_recepcion":0,"autoria_licencia":PIE});
 save(&base.join("DICTAMEN-REPLICA.json"),&out)?;
 let m=load(&base.join("METRICAS-RUST.json"))?;need(m["conforme"]==true&&m["totales"]["total_tokens"]==r["tokens_totales_conocidos"],"Métricas discordantes")?;
 let web=format!(r#"<!doctype html><html lang="es"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; base-uri 'none'; form-action 'none'"><title>SV · MD01 · Réplica diagnóstica</title><style>body{{font:18px/1.55 system-ui;max-width:1050px;margin:2rem auto;padding:0 1rem;color:#163044;background:#f8fafb}}h1{{font-size:2rem}}table{{border-collapse:collapse;width:100%}}td,th{{border:1px solid #bac7cf;padding:.7rem;text-align:left}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.85rem}}details{{margin:1rem 0}}.aviso{{border-left:5px solid #c38200;padding:1rem;background:#fff2d5}}footer{{font-size:.8rem}}</style><h1>MD01 · Réplica diagnóstica</h1><p><strong>{}</strong> · GPT-6 Astra · nodo 03 · 08/10/2026</p><p>Una pregunta, tres etapas: provisional, autocrítica y verificación final neutral. 0 significa correcto y completo. Criticidad conservada; la conformidad exige contenido, estructura y revisión correctos.</p><table><tr><th>Etapa</th><th>Valor</th><th>Fundamento exterior al candidato</th></tr>{}</table><p class="aviso">⚠ {}</p><p>La etapa R2 reconoce: «Los identificadores históricos 0 y 1 permanecen válidos para sus respectivas entregas».</p><h2>Instrumentación recibida</h2><p>Duración del banco: {} ms. Tokens: {} de entrada, {} de salida; {} total. {} muestras del cliente; intervalo máximo {} ms; sin fallos de medición. Tres HTTP 200 / response.completed, sin reintentos. Tiempo HTTP agregado: {} ms; {} sucesos SSE.</p><p>El control, suministro y medición propios se realizaron en Rust. Herramientas del candidato deshabilitadas y consulta exterior prohibida por contrato; esto no demuestra aislamiento de la infraestructura interna de OpenAI. Los fundamentos son explicaciones documentales verificables; no se recibió un resumen de razonamiento del proveedor.</p><p>Créditos e importe atribuibles: desconocidos; conciliación pendiente. El número de tokens no se convierte en dinero sin fuente de facturación.</p><h2>Alcance del resultado</h2><p>{}</p><p>{} Las tres etapas pertenecen a una misma pregunta; no forman un vector de tres preguntas ni un nuevo polígono de nueve. El resultado histórico permanece bajo reserva metodológica.</p><h2>Entregas conservadas</h2>{}<footer>{}</footer></html>"#,
 html(verdict),filas,html(rv["advertencia_documental"].as_str().unwrap()),r["duracion_banco_ms"],r["tokens_entrada_conocidos"],r["tokens_salida_conocidos"],r["tokens_totales_conocidos"],r["muestras"],r["intervalo_maximo_ms"],m["totales"]["duracion_ms"],m["totales"]["eventos_sse"],html(rv["limites"].as_str().unwrap()),html(rv["naturaleza"].as_str().unwrap()),respuestas,html(PIE));
 let p=base.join("web/RESULTADO-MD01.html");fs::create_dir_all(p.parent().unwrap()).map_err(e)?;if p.exists(){need(read(&p)?==web.as_bytes(),"Vista previa distinta")?;}else{let mut f=OpenOptions::new().create_new(true).write(true).open(&p).map_err(e)?;f.write_all(web.as_bytes()).map_err(e)?;}
 Ok(json!({"dictamen":verdict,"etapas":resultados.iter().map(|x|x["valor"].clone()).collect::<Vec<_>>(),"tokens":r["tokens_totales_conocidos"]}))
}
#[cfg(test)]mod tests{use super::*;#[test]fn error_no_se_compensa_y_u_no_es_conformidad(){for(c,r,f,w)in[("0","1",true,"1"),("1","0",true,"1"),("U","0",true,"U"),("0","U",true,"U"),("0","0",false,"1"),("0","0",true,"0")] {assert_eq!(valor(c,r,f).unwrap(),w);}assert!(valor("Apto","0",true).is_err());}#[test]fn respuesta_no_inyecta_html(){assert_eq!(html("<script>&\""),"&lt;script&gt;&amp;&quot;");}}

